export const REQUIRED_GOOGLE_FONTS = ["Inter", "Lato", "Libre Baskerville", "Manrope", "Merriweather", "Montserrat", "Nunito", "Open Sans", "Playfair Display", "Poppins", "Roboto", "Rubik", "Source Sans 3", "Work Sans"];

export const seriesById = (id: string) => TEMPLATE_SERIES.find((s) => s.id === id);
export const freeSeries = () => TEMPLATE_SERIES.filter((s) => s.tier === "free");
export const gdocFor = (id: string, doc: GDocLink["doc"], size: "a4" | "letter", pages = 1) =>
  seriesById(id)?.gdocs.find((g) => g.doc === doc && g.size === size && (doc !== "resume" || g.pages === pages));
